313	class PgProducts implements ProductRepository {
314	    private final Connection c;
315	
316	    PgProducts(Connection c) {
317	        this.c = c;
318	    }
319	
320	    @Override
321	    public Optional<Product> find(String sku) {
322	        return Jdbc.call(() -> {
323	            try (PreparedStatement ps = c.prepareStatement(
324	                    "SELECT sku, name, price, weight_kg, stock, discontinued FROM products WHERE sku = ?")) {
325	                ps.setString(1, sku);
326	                try (ResultSet rs = ps.executeQuery()) {
327	                    if (!rs.next()) {
328	                        return Optional.empty();
329	                    }
330	                    return Optional.of(new Product(rs.getString("sku"), rs.getString("name"),
331	                            rs.getBigDecimal("price"), rs.getBigDecimal("weight_kg"), rs.getInt("stock"),
332	                            rs.getBoolean("discontinued")));
333	                }
334	            }
335	        });
336	    }
337	
338	    @Override
339	    public void insertIfAbsent(Product p) {
340	        Jdbc.call(() -> {
341	            try (PreparedStatement ps = c.prepareStatement(
342	                    "INSERT INTO products(sku, name, price, weight_kg, stock, discontinued) "
343	                            + "VALUES (?, ?, ?, ?, ?, ?) ON CONFLICT (sku) DO NOTHING")) {
344	                ps.setString(1, p.sku());
345	                ps.setString(2, p.name());
346	                ps.setBigDecimal(3, p.price());
347	                ps.setBigDecimal(4, p.weightKg());
348	                ps.setInt(5, p.stock());
349	                ps.setBoolean(6, p.discontinued());
350	                ps.executeUpdate();
351	            }
352	            return null;
353	        });
354	    }
355	
356	    @Override
357	    public boolean tryDebit(List<CartItem> items) {
358	        return Jdbc.call(() -> {
359	            // Trava as linhas em ordem de SKU: pagamentos simultâneos não se travam um ao outro.
360	            String[] skus = items.stream().map(CartItem::sku).sorted().toArray(String[]::new);
361	            Map<String, Integer> stock = new HashMap<>();
362	            try (PreparedStatement ps = c.prepareStatement(
363	                    "SELECT sku, stock FROM products WHERE sku = ANY(?) ORDER BY sku FOR UPDATE")) {
364	                ps.setArray(1, c.createArrayOf("text", skus));
365	                try (ResultSet rs = ps.executeQuery()) {
366	                    while (rs.next()) {
367	                        stock.put(rs.getString("sku"), rs.getInt("stock"));
368	                    }
369	                }
370	            }
371	            for (CartItem item : items) {
372	                Integer available = stock.get(item.sku());
373	                if (available == null || available < item.quantity()) {
374	                    return false;
375	                }
376	            }
377	            adjust(items, -1);
378	            return true;
379	        });
380	    }
381	
382	    @Override
383	    public void restore(List<CartItem> items) {
384	        Jdbc.call(() -> {
385	            adjust(items, 1);
386	            return null;
387	        });
388	    }
389	
390	    private void adjust(List<CartItem> items, int sign) throws java.sql.SQLException {
391	        try (PreparedStatement ps = c.prepareStatement("UPDATE products SET stock = stock + ? WHERE sku = ?")) {
392	            for (CartItem item : items) {
393	                ps.setInt(1, sign * item.quantity());
394	                ps.setString(2, item.sku());
395	                ps.addBatch();
396	            }
397	            ps.executeBatch();
398	        }
399	    }
400	}

